{"command":"python3 << 'EOF'
import csv

# Check for any city names with special characters that might need quoting
with open('outputs/t02_eurostat_raw.csv', 'r') as f:
    reader = csv.DictReader(f)
    special_chars = []
    for row in reader:
        city_name = row['city_name']
        if ',' in city_name or '"' in city_name or '\n' in city_name:
            special_chars.append(city_name)

    if special_chars:
        print("City names with special characters:")
        for name in set(special_chars):
            print(f"  {name}")
    else:
        print("No city names with special characters found")
EOF"}
